from format_lecon import Lesson,paras,steps,table,ABBR
from medicaments import adrenaline
from angio_medicaments import cetirizine,berinert,icatibant
ABBR.update({'C1-INH':'inhibiteur de la C1 estérase','C1q':'composant C1q du complément','C4':'composant C4 du complément','H1':'récepteur de l’histamine de type 1','B2':'récepteur de la bradykinine de type 2'})
l=Lesson('Angio-œdème',9);a=adrenaline(l);c=cetirizine(l);b=berinert(l);i=icatibant(l)
l.add('L’{angio-œdème} est un gonflement profond de la peau ou des muqueuses. Les paupières peuvent être atteintes avec les lèvres ou d’autres sites. La priorité est de rechercher une menace respiratoire, puis d’identifier le mécanisme.',paras('L’augmentation de perméabilité vasculaire fait passer du liquide dans les tissus profonds. Une paupière gonflée peut être la partie visible d’une réaction plus étendue. Inspecter le visage ne suffit donc pas à juger les voies aériennes.', 'Les formes mastocytaires, souvent liées à l’histamine, diffèrent des formes liées à la bradykinine. Les traitements et les explorations ne sont pas interchangeables. Toutes les formes mastocytaires ne correspondent pas à une allergie identifiée.', 'Le terme historique œdème de Quincke ne précise pas le médiateur. Il ne doit pas remplacer une description de la localisation, de la gravité et du contexte.'),(16,54,55))
l.add('Le {contexte clinique} distingue exposition, médicament et maladie récidivante. Un traitement ancien peut être responsable. Une histoire familiale négative n’exclut pas une forme héréditaire.',paras('Rechercher aliment, piqûre, médicament ou exposition temporellement plausible, sans attribuer chaque épisode à la dernière substance consommée. Une urticaire spontanée peut accompagner un angio-œdème sans allergène causal démontré.', 'Les inhibiteurs de l’enzyme de conversion peuvent provoquer un épisode après plusieurs années de prise. Ils doivent figurer dans la revue médicamenteuse même en l’absence de modification récente. D’autres traitements peuvent aussi contribuer selon le mécanisme.', 'Crises répétées, douleurs abdominales inexpliquées et antécédents familiaux orientent vers une forme héréditaire. Un début plus tardif sans histoire familiale peut conduire à rechercher une forme acquise et une maladie associée.', 'Les séries étrangères ne permettent pas d’attribuer un pourcentage précis aux causes d’œdème palpébral en Suisse. Le raisonnement repose ici sur le profil clinique et les examens adaptés.'),(16,54,55))
l.add('La {physiopathologie} explique la différence de réponse au traitement. Histamine et bradykinine augmentent toutes deux la perméabilité vasculaire. Un même aspect palpébral ne permet pas de choisir le médicament à lui seul.',paras('Dans les formes mastocytaires, les médiateurs peuvent produire prurit, plaques urticariennes et signes systémiques. Une anaphylaxie ajoute une menace des voies aériennes, de la respiration ou de la circulation.', 'Un déficit ou un dysfonctionnement du C1-inhibiteur favorise l’activation du système de contact et la formation de bradykinine. Un inhibiteur de l’enzyme de conversion peut réduire sa dégradation. Ces mécanismes ne relèvent pas d’un blocage H1 seul.', 'L’absence d’urticaire et la faible réponse aux antihistaminiques orientent vers une forme à bradykinine sans suffire à la prouver. Une urticaire concomitante n’exclut pas automatiquement une maladie héréditaire.', 'Certaines formes héréditaires ont une concentration et une fonction normales du C1-inhibiteur. Le bilan ne se résume donc pas à une valeur isolée normale.'),(16,54,55))
l.add('La démarche recherche les {signes vitaux menacés}. Une modification de voix, une langue qui gonfle ou une gêne respiratoire est urgente. Une atteinte cutanée isolée ne suffit pas à définir une anaphylaxie.',table(['Signe','Conduite'],[['Voix rauque, stridor, gêne à avaler ou salive mal déglutie','Appel urgent et évaluation des voies aériennes.'],['Dyspnée, bronchospasme, hypoxémie','Prise en charge immédiate ; anaphylaxie à envisager.'],['Malaise, hypotension ou collapsus','Réanimation urgente ; adrénaline si anaphylaxie.'],['Aggravation rapide du visage ou de la langue','Ne pas attendre un bilan de complément.'],['Douleur oculaire, diplopie ou baisse visuelle','Rechercher une urgence orbitaire distincte.'],['Paupières gonflées sans signe systémique','Examen et surveillance adaptés ; pas d’étiquette automatique d’anaphylaxie.']]),(9,14,16,54))
l.add('L’{anamnèse} recherche la chronologie et les symptômes associés. Les urgences sont traitées pendant le recueil. Une histoire d’épisodes antérieurs permet ensuite de préparer l’enquête.',steps('Préciser heure de début, progression et sites atteints.', 'Demander voix modifiée, déglutition difficile, dyspnée, malaise et douleurs abdominales.', 'Rechercher prurit, urticaire et exposition plausible.', 'Recueillir tous les médicaments, y compris anciens traitements et automédication.', 'Demander crises précédentes, réponses réelles aux traitements et histoire familiale.', 'Chez un patient connu, consulter la carte et le plan d’urgence sans retarder la prise en charge.'),(14,16,54,55))
l.add('L’{examen} évalue d’abord respiration et circulation. Il documente ensuite l’étendue cutanée et oculaire. L’amélioration des paupières ne suffit pas à conclure que le danger est écarté.',paras('Contrôler vigilance, pression artérielle, fréquence cardiaque, fréquence respiratoire et saturation selon le contexte. Écouter la voix et rechercher stridor ou sibilances. Une saturation encore normale n’annule pas une menace laryngée clinique.', 'Inspecter lèvres, langue et région buccale sans geste traumatique ni retard d’appel. Une exploration des voies aériennes nécessite un cadre adapté. L’intubation difficile potentielle doit être anticipée par une équipe expérimentée.', 'Décrire plaques urticariennes, prurit et autres sites gonflés. Examiner les paupières et vérifier acuité, pupilles et motilité lorsqu’une cause oculaire reste possible. Douleur focale, chaleur, pus ou fièvre orientent aussi vers une infection.', 'Répéter l’examen après traitement et dater l’évolution. Un changement de voix ou une nouvelle gêne respiratoire impose une réévaluation immédiate.'),(9,14,16,54))
l.add('L’{approche syndromique} sépare les mécanismes et les imitateurs. Le traitement d’urgence ne dépend pas d’une certitude étiologique complète. L’absence de réponse conduit à revoir l’hypothèse.',table(['Profil','Orientation'],[['Gonflement avec prurit ou urticaire','Mécanisme mastocytaire possible ; rechercher anaphylaxie.'],['Atteinte respiratoire ou circulatoire aiguë compatible','Anaphylaxie : adrénaline intramusculaire et secours.'],['Crises sans urticaire, douleurs abdominales, contexte familial','Explorer une forme héréditaire à bradykinine.'],['Prise d’IEC, même ancienne','Évoquer un effet médicamenteux et arrêter l’IEC impliqué.'],['Début tardif et déficit acquis suspecté','Rechercher notamment une affection hématologique ou auto-immune.'],['Desquamation, exposition locale, brûlure','Dermatite de contact possible.'],['Tuméfaction douloureuse chaude ou signes orbitaires','Rechercher infection préseptale, orbitaire ou lacrymale.']]),(9,16,54,55))
l.add('Le {diagnostic positif} reconnaît le gonflement profond et son évolution. Le mécanisme est établi par le contexte et, si nécessaire, des examens spécialisés. Un test allergique isolé n’établit pas la cause.',paras('L’anaphylaxie est un diagnostic clinique d’urgence. Des signes cutanés peuvent manquer. Le traitement ne doit pas attendre une tryptase, un dosage du complément ou une consultation allergologique.', 'Une forme mastocytaire peut survenir sans urticaire visible au moment de l’examen. À l’inverse, des plaques concomitantes n’excluent pas toute forme héréditaire. Utiliser ces indices sans en faire des règles absolues.', 'Pour une suspicion de déficit du C1-inhibiteur, concentration, fonction et C4 sont interprétés ensemble. Une discordance clinique-biologique demande une confirmation et un avis spécialisé. Des formes à C1-inhibiteur normal nécessitent une autre démarche.'),(14,16,54))
l.add('Les {examens complémentaires} sont ciblés après sécurisation. Ils recherchent le mécanisme et les causes associées. Aucun résultat ne remplace l’évaluation des voies aériennes.', '<h3>9.a — Phase aiguë</h3>'+paras('L’anaphylaxie se traite sur ses signes cliniques. Les prélèvements demandés par l’équipe ne doivent pas retarder l’adrénaline. Le bilan étiologique est organisé après la stabilisation.')+'<h3>9.b — Complément</h3>'+paras('C4, concentration et activité du C1-inhibiteur sont utiles devant une suspicion de forme héréditaire ou acquise. Le spécialiste décide des répétitions et des analyses génétiques. L’âge et la grossesse influencent l’interprétation.')+'<h3>9.c — Forme acquise</h3>'+paras('C1q, anticorps dirigés contre le C1-inhibiteur et recherche d’une affection hématologique ou auto-immune peuvent être indiqués. Le choix dépend de l’âge de début, du contexte et du bilan initial.')+'<h3>9.d — Allergologie</h3>'+paras('Tests cutanés ou examens sanguins répondent à une exposition plausible. Une sensibilisation ne prouve pas une causalité. La cétirizine peut modifier les tests cutanés ; toute interruption est organisée avec le service selon la sécurité clinique.'),(14,16,51,54))
l.add('L’{arbre décisionnel} privilégie les fonctions vitales. La distinction de mécanisme guide ensuite le traitement spécifique. Un doute ne justifie pas de différer le traitement d’une anaphylaxie suspectée.',steps('Rechercher immédiatement atteinte des voies aériennes, respiration et circulation.', 'Si anaphylaxie suspectée, appeler le 144 ou l’équipe d’urgence et administrer l’adrénaline intramusculaire adaptée.', 'Si mécanisme à bradykinine connu ou fortement suspecté avec menace, sécuriser les voies aériennes et accéder au traitement spécifique spécialisé.', 'En l’absence de menace, évaluer mécanisme, médicament et cause oculaire éventuelle.', 'Arrêter l’IEC impliqué et organiser son remplacement médical ; ne pas réintroduire un autre IEC après un épisode imputé à cette classe.', 'Organiser surveillance, bilan ciblé et plan écrit de récidive.'),(13,14,16,52,53,54,55))
l.add('La {prise en charge en Suisse} dépend du mécanisme et de la gravité. Les traitements cutanés ne remplacent pas la réanimation. Les indications suisses sont distinguées des recommandations internationales et des emplois hors indication.', '<h3>11.A — Objectifs</h3>'+paras('Préserver les voies aériennes et la circulation, contrôler la crise et prévenir une réexposition dangereuse. Une hospitalisation et une surveillance sont adaptées au risque, sans durée unique imposée pour tous les épisodes.')+'<h3>11.B — Traitements</h3>'+paras('Anaphylaxie : adrénaline intramusculaire précoce, appel de secours et surveillance. Éviter de faire lever brusquement le patient ; adapter la position à la respiration et à l’état circulatoire. L’équipe assure oxygène, accès veineux et remplissage si nécessaire.')+a+paras('Une nouvelle dose intramusculaire est recommandée après cinq minutes si les signes respiratoires ou circulatoires persistent selon le guide cité. Une réponse insuffisante après deux doses adaptées nécessite une aide experte. Les corticoïdes ne sont pas systématiques et les antihistaminiques ne traitent pas le choc.', 'Manifestations mastocytaires cutanées sans menace : un antihistaminique peut être retenu après évaluation. La fiche suivante distingue l’indication autorisée de la spécialité et l’usage dans un angio-œdème aigu :')+c+paras('Angio-œdème héréditaire : le plan spécialisé prévoit un traitement de crise précoce. Les deux options suisses détaillées ci-dessous ont des voies, doses et limites différentes :')+b+i+paras('Ces doses ne constituent pas une autorisation générale d’utiliser les produits pour tout œdème sous IEC ou tout déficit acquis. Un emploi hors indication se décide par l’équipe experte. L’atteinte laryngée impose des soins urgents même après une injection à domicile.', 'Une forme à bradykinine établie ne répond pas aux antihistaminiques, aux corticoïdes ni à l’adrénaline comme traitement de son mécanisme. Si l’anaphylaxie reste plausible devant une urgence indifférenciée, administrer l’adrénaline adaptée sans attendre la confirmation du mécanisme.', 'L’IEC impliqué est arrêté immédiatement et n’est pas réintroduit. Le remplacement cardiovasculaire est organisé avec le prescripteur. Une persistance ou une récidive justifie une réévaluation plutôt qu’une réintroduction empirique.')+'<h3>11.C — Surveillance</h3>'+paras('Surveiller voix, langue, respiration, circulation, extension et réponse. Adapter la durée d’observation au mécanisme, à la gravité et au risque de récidive. Une prise orale est évitée si la déglutition est compromise.', 'La grossesse et l’allaitement nécessitent un choix spécialisé. Pour la forme héréditaire, le C1-inhibiteur plasmatique est privilégié par les recommandations citées. Les précautions propres à chaque notice restent explicites dans les fenêtres.')+'<h3>11.D — Suites</h3>'+paras('Après anaphylaxie, organiser l’évaluation allergologique, le plan d’urgence et, si indiqué, un auto-injecteur avec formation. Après une forme héréditaire, vérifier l’accès au traitement de crise, la carte et la formation. La prophylaxie au long cours est individualisée par le centre spécialisé.'),(13,14,16,51,52,53,54,55))
l.add('La {prévention} repose sur un diagnostic précis et un plan utilisable. Une éviction alimentaire générale n’est pas justifiée sans cause établie. Les traitements déclenchants et les procédures à risque doivent être signalés.',paras('Noter la réaction et les médicaments impliqués dans le dossier. Informer patient et soignants de l’interdiction de réexposition à l’IEC lorsqu’il est responsable. Le choix d’une autre classe est médical.', 'Pour une forme héréditaire, anticiper chirurgie, soins dentaires et facteurs personnels avec le spécialiste. Le dépistage familial est discuté. Un traitement préventif ne dispense pas de disposer d’un traitement de crise.', 'Vérifier compréhension, disponibilité et technique du traitement d’urgence prescrit. Les proches et, pour l’enfant, les personnes responsables doivent connaître la conduite prévue.'),(14,16,54,55))
l.add('Les {points clés} évitent les raccourcis dangereux. La gravité ne se mesure pas seulement au volume palpébral. Un traitement adapté à un mécanisme peut être inefficace pour un autre.',steps('Évaluer langue, voix, respiration et circulation.', 'Traiter immédiatement une anaphylaxie suspectée.', 'Rechercher les médicaments anciens comme les nouveaux.', 'Ne pas réduire l’angio-œdème à une allergie.', 'Une urticaire concomitante n’exclut pas absolument une forme héréditaire.', 'Les schémas pédiatriques et les voies des médicaments spécifiques sont distincts.'),(14,16,52,53,54,55))
l.quiz([('Le volume des paupières prédit-il seul le risque laryngé ?','Non. La voix, la langue, la déglutition et la respiration doivent être évaluées.'),('Tout angio-œdème est-il allergique ?','Non. Il existe notamment des formes à bradykinine.'),('Une peau normale exclut-elle l’anaphylaxie ?','Non.'),('Quel traitement est prioritaire dans l’anaphylaxie avec menace respiratoire ou circulatoire ?','L’adrénaline intramusculaire précoce avec appel de secours.'),('La cétirizine remplace-t-elle l’adrénaline dans le choc ?','Non.'),('La solution d’adrénaline à 1 mg/ml est-elle un bolus intraveineux de routine pour l’anaphylaxie ?','Non.'),('Un IEC pris depuis plusieurs années peut-il être responsable ?','Oui.'),('Peut-on reprendre un autre IEC après un angio-œdème imputé à cette classe ?','Non.'),('Une histoire familiale négative exclut-elle une forme héréditaire ?','Non.'),('Une urticaire concomitante exclut-elle absolument cette maladie ?','Non. Le contexte complet et le bilan comptent.'),('Quels examens explorent un déficit du C1-inhibiteur ?','Sa concentration et sa fonction, avec C4 et examens complémentaires selon le spécialiste.'),('Quelle est la dose unitaire suisse de Berinert IV citée ?','20 unités internationales par kilogramme, par voie intraveineuse selon la notice.'),('Les répétitions adultes de Firazyr s’appliquent-elles automatiquement à l’enfant ?','Non. Les paliers pédiatriques et les limites de données sont spécifiques.'),('Une injection à domicile permet-elle de rester seul avec un œdème laryngé ?','Non. Une évaluation et une surveillance médicales urgentes sont nécessaires.')],(13,14,16,51,52,53,54,55))
l.write()
